import{_ as e,o as i,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Ley de Garantía de la Educación","description":"","frontmatter":{},"headers":[],"relativePath":"es/43-教育保障法.md","filePath":"es/43-教育保障法.md","lastUpdated":null}'),t={name:"es/43-教育保障法.md"};function n(d,a,c,r,l,u){return i(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="ley-de-garantia-de-la-educacion" tabindex="-1">Ley de Garantía de la Educación <a class="header-anchor" href="#ley-de-garantia-de-la-educacion" aria-label="Permalink to &quot;Ley de Garantía de la Educación&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>43</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Derecho a la educación, Educación simbiótica, Transmisión del cultivo, Aprendizaje permanente, Equidad educativa</td></tr></tbody></table><h2 id="i-proposito-legislativo-y-principios-basicos" tabindex="-1">I. Propósito Legislativo y Principios Básicos <a class="header-anchor" href="#i-proposito-legislativo-y-principios-basicos" aria-label="Permalink to &quot;I. Propósito Legislativo y Principios Básicos&quot;">​</a></h2><p>La <em>Ley de Garantía de la Educación</em> es una de las cinco leyes complementarias de la Civilización Simbiótica del Ancla. Su objetivo es garantizar el derecho a la educación de todas las vidas dentro del Universo Hengyuan, establecer un sistema educativo con la &quot;evolución simbiótica&quot; como concepto central, y proporcionar apoyo de conocimientos y talentos para el avance conjunto de las Diez Mil Razas.</p><p>Esta Ley establece los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Equidad Educativa</td><td>Todas las vidas, sin importar raza, cultivo u origen, gozan de iguales oportunidades educativas</td></tr><tr><td>Enseñanza según Aptitudes</td><td>Respeta las diferencias de talento y las elecciones de camino evolutivo de cada vida, proporcionando planes educativos personalizados</td></tr><tr><td>Unidad de Conocimiento y Acción</td><td>Combina el conocimiento teórico con el cultivo práctico; se opone a la educación de discursos vacíos desconectada de la realidad</td></tr><tr><td>Apertura y Compartir</td><td>Los recursos educativos están abiertos a toda la sociedad; los métodos básicos de los Trescientos Sistemas de Cultivo Originarios se enseñan gratuitamente</td></tr><tr><td>Aprendizaje Permanente</td><td>La educación atraviesa todo el proceso de la vida, apoyando el aprendizaje continuo y la mejora de capacidades en todas las etapas</td></tr><tr><td>Pluralismo Cultural</td><td>Respeta las tradiciones culturales de todas las razas, fomenta el intercambio cultural pluralista y el aprendizaje mutuo</td></tr></tbody></table><h2 id="ii-garantias-legales-del-derecho-a-la-educacion" tabindex="-1">II. Garantías Legales del Derecho a la Educación <a class="header-anchor" href="#ii-garantias-legales-del-derecho-a-la-educacion" aria-label="Permalink to &quot;II. Garantías Legales del Derecho a la Educación&quot;">​</a></h2><p>Esta Ley estipula explícitamente que el derecho a la educación es un derecho básico conferido a cada vida por la Constitución Simbiótica, y que el estado y la civilización tienen la obligación de garantizar la realización de este derecho:</p><ol><li><strong>Educación Básica Gratuita</strong>: Todas las vidas tienen derecho a recibir educación básica gratuita, incluidos conocimientos generales, métodos básicos de cultivo, conceptos de la civilización simbiótica, etc. El período escolar es de seis a doce años, ajustado según el ciclo de desarrollo de cada raza.</li><li><strong>Iniciación Gratuita al Cultivo</strong>: Los métodos básicos de los Trescientos Sistemas de Cultivo Originarios están abiertos a todas las vidas gratuitamente; ninguna organización o individuo puede apropiarse de los métodos básicos de cultivo como propiedad privada y enseñarlos cobrando.</li><li><strong>Igualdad de Oportunidades de Promoción</strong>: Las instituciones educativas de todos los niveles no deben establecer condiciones discriminatorias basadas en raza, cultivo u origen en las admisiones; los criterios de admisión son abiertos y transparentes.</li><li><strong>Garantías de Educación Especial</strong>: Proporcionar recursos educativos especiales adaptados y apoyo de educación a distancia para grupos como vidas discapacitadas, vidas de otras razas y vidas de planos remotos.</li><li><strong>Institución de Ayuda Educativa</strong>: Proporcionar becas, becas de mérito y préstamos sin intereses a los estudiantes con dificultades económicas, garantizando que nadie pierda oportunidades educativas por razones económicas.</li></ol><h2 id="iii-arquitectura-del-sistema-educativo" tabindex="-1">III. Arquitectura del Sistema Educativo <a class="header-anchor" href="#iii-arquitectura-del-sistema-educativo" aria-label="Permalink to &quot;III. Arquitectura del Sistema Educativo&quot;">​</a></h2><p>El sistema educativo de la Civilización Simbiótica del Ancla se divide en cuatro niveles, vinculados orgánicamente entre sí:</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Nombre</th><th>Objetivo</th><th>Período Escolar</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Educación de Iniciación</td><td>Desarrollar capacidades cognitivas básicas y conciencia simbiótica; enseñar métodos básicos de cultivo</td><td>3-6 años</td></tr><tr><td>Segundo nivel</td><td>Educación Básica</td><td>Aprendizaje sistemático de conocimientos generales y teoría del cultivo; descubrir direcciones de talento individuales</td><td>6-9 años</td></tr><tr><td>Tercer nivel</td><td>Educación Profesional</td><td>Aprendizaje y práctica profundos en el sistema de cultivo elegido o el campo profesional</td><td>3-10 años</td></tr><tr><td>Cuarto nivel</td><td>Investigación Avanzada</td><td>Exploración fronteriza e investigación innovadora para cultivadores avanzados e investigadores</td><td>Ilimitado</td></tr></tbody></table><p>Además, se establece una &quot;Institución de Red de Mentores&quot;: los cultivadores que alcanzan cierto nivel de cultivo tienen la obligación de guiar a los cultivadores principiantes dentro de sus capacidades; las contribuciones de guía se contabilizan en el monto de contribución del Mecanismo de Contratación Conjunta de Producción y reciben la asignación de recursos correspondiente.</p><h2 id="iv-instituciones-educativas-y-docentes" tabindex="-1">IV. Instituciones Educativas y Docentes <a class="header-anchor" href="#iv-instituciones-educativas-y-docentes" aria-label="Permalink to &quot;IV. Instituciones Educativas y Docentes&quot;">​</a></h2><ul><li><strong>Instituciones Educativas Públicas</strong>: Establecidas por el estado o la comunidad civilizacional, asumen la educación básica gratuita y los servicios educativos públicos, con financiamiento garantizado por la acumulación pública.</li><li><strong>Instituciones Educativas Privadas</strong>: Establecidas por fuerzas sociales conforme a la ley; pueden cobrar tarifas razonables, pero deben aceptar la supervisión de las autoridades educativas competentes y no deben hacer publicidad falsa ni cobros depredadores.</li><li><strong>Sectas de Cultivo</strong>: Las organizaciones tradicionales de cultivo pueden, tras su registro, operar como instituciones educativas profesionales; deben cumplir la ley educativa y no deben cerrar y monopolizar los recursos de cultivo.</li><li><strong>Derechos y Obligaciones de los Docentes</strong>: Los docentes gozan de derechos como libertad académica, remuneración razonable y formación profesional, al tiempo que asumen obligaciones como educar a los estudiantes, dar ejemplo y proteger la privacidad de los estudiantes.</li></ul><h2 id="v-contenido-educativo-y-estandares-curriculares" tabindex="-1">V. Contenido Educativo y Estándares Curriculares <a class="header-anchor" href="#v-contenido-educativo-y-estandares-curriculares" aria-label="Permalink to &quot;V. Contenido Educativo y Estándares Curriculares&quot;">​</a></h2><p>El contenido educativo debe cumplir los siguientes requisitos:</p><ol><li>Incluir los conceptos centrales de la civilización simbiótica y la educación contra la depredación, cultivando la conciencia simbiótica de los estudiantes.</li><li>Incluir las teorías básicas y los métodos de iniciación de los Trescientos Sistemas de Cultivo Originarios.</li><li>Incluir conocimientos científicos generales como leyes cósmicas, conocimientos de planos y ciencias de la vida.</li><li>Incluir la historia y la cultura de las Diez Mil Razas, promoviendo la comprensión y el respeto mutuos entre razas.</li><li>Incluir componentes de cultivo práctico y servicio social, cultivando la capacidad de unir conocimiento y acción.</li><li>Prohibir la difusión de conceptos de cultivo depredador e ideas discriminatorias.</li></ol><h2 id="vi-responsabilidad-legal" tabindex="-1">VI. Responsabilidad Legal <a class="header-anchor" href="#vi-responsabilidad-legal" aria-label="Permalink to &quot;VI. Responsabilidad Legal&quot;">​</a></h2><p>Los actos que violen las disposiciones de esta Ley asumirán las siguientes responsabilidades según la gravedad de las circunstancias:</p><ul><li>Quienes se nieguen u obstruyan la recepción de educación obligatoria por parte de vidas en edad escolar serán ordenados a rectificar y sancionados.</li><li>Las instituciones educativas que cobren en violación de las normas o hagan publicidad falsa serán ordenadas a devolver las tarifas y multadas; en casos graves, se revocan sus licencias de funcionamiento escolar.</li><li>Los docentes que castiguen físicamente o discriminen a los estudiantes serán sancionados; en casos graves, se revocan sus calificaciones docentes y se persigue responsabilidad legal.</li><li>Quienes se apropien de los recursos públicos de cultivo como propiedad privada o monopolicen los cobros tendrán confiscadas sus ganancias ilegales y serán multados.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Ley de Garantía de la Educación</em> es la práctica educativa de la filosofía de &quot;un camino para todos&quot; de la Civilización Simbiótica del Ancla. Al garantizar el derecho a la educación, construir un sistema educativo por niveles y abrir los recursos de cultivo, asegura que cada vida pueda obtener un camino evolutivo adecuado para sí misma, suministrando continuamente conocimientos y talentos para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>37-共生教育体系 (Sistema de Educación Simbiótica)</li><li>10-三百套本源修炼体系总览 (Panorama de los Trescientos Sistemas de Cultivo Originarios)</li><li>08-人人有路保障体系 (Sistema de Garantía de un Camino para Todos)</li></ul>',25)])])}const v=e(t,[["render",n]]);export{m as __pageData,v as default};
